<template><view class="wish-page"><k-topbar title="资质与收款资料" back :fab="false"/><view class="w-body"><view class="wc-heading"><view class="wc-heading__icon"><k-icon name="badge-check" :size="35" color="#102c46"/></view><text class="w-title">一份凭证，<br/>多一份信任。</text><text class="w-caption">资料仅本人及平台审核人员可见，不公开展示。</text></view><view class="w-card"><text class="w-heading">选择资料类型</text><view class="w-pills w-section"><view v-for="t in types" :key="t.key" class="w-pill" :class="{on:type===t.key}" @click="type=t.key;file=''">{{t.label}}</view></view><text class="w-caption">{{tip}}</text><view v-if="type==='permit'" class="w-field"><text class="w-field__label">许可城市</text><input v-model="city" placeholder="与心愿帮忙地一致" maxlength="80"/></view><view v-if="type!=='payout'" class="w-field wc-dates"><text class="w-field__label">证件生效日期</text><picker mode="date" :value="validFrom" @change="validFrom=$event.detail.value"><view class="w-input">{{validFrom||'选择证件生效日期'}}</view></picker><text class="w-field__label">有效期止</text><picker mode="date" :value="validUntil" @change="validUntil=$event.detail.value"><view class="w-input">{{validUntil||'选择证件有效期止'}}</view></picker></view><view v-if="type==='permit'" class="w-field"><text class="w-field__label">许可范围</text><view class="w-pills"><view v-for="s in scopes" :key="s.key" class="w-pill" :class="{on:permitType===s.key}" @click="permitType=s.key">{{s.label}}</view></view></view><view class="wc-upload" @click="pick"><k-icon :name="file?'file-check':'upload'" :size="33" color="#3166f5"/><text>{{file?'文件已选择，点击更换':'上传清晰、完整的资料'}}</text><text>{{file?'提交后等待平台审核':'JPG / PNG ≤20MB，PDF ≤10MB'}}</text></view><view class="w-tip"><k-icon name="lock-keyhole" :size="18" color="#3166f5"/><text>{{type==='payout'?'请上传本人收款账户资料，包含开户人、银行名称及账号。请勿上传密码、验证码或卡片背面安全码。':type==='permit'?'许可必须适用于心愿所在城市，审核通过后才能承接对应地区的烟酒类心愿。':'食品类提供健康证或食品经营许可证任一项即可。证件需真实有效，审核通过后才能承接相应心愿。'}}</text></view><button class="w-primary w-section" :disabled="busy||!file" @click="submit">{{busy?'提交中…':'提交审核'}}<k-icon name="arrow-right" :size="21" color="#e7f58a"/></button></view><view class="w-between w-section"><text class="w-heading">我的提交记录</text><button class="w-link" @click="load">刷新</button></view><view v-if="error" class="w-tip">{{error}}</view><view v-for="r in rows" :key="r.credentialId" class="w-card wc-record"><view class="w-between"><text>{{types.find(t=>t.key===r.type)?.label||r.type}}</text><text class="w-tag" :class="{'w-tag--lime':stateLabel(r)==='已通过'}">{{stateLabel(r)}}</text></view><text class="w-caption">{{r.city||'平台审核'}} · {{String(r.createTime).slice(0,10)}}</text><text v-if="r.type!=='payout'" class="w-caption">有效期 {{r.validFrom||'待补充核实'}} 至 {{r.validUntil||'待补充核实'}}</text><text v-if="r.type==='permit'" class="w-caption">许可范围 {{({2:'烟草',4:'酒类',6:'烟草及酒类'})[r.permitScope]||'待补充核实'}}</text><text v-if="r.note" class="w-caption">审核说明：{{r.note}}</text><button class="w-link" @click="view(r)">查看已提交文件 →</button></view><view v-if="!rows.length&&!error" class="w-state"><text class="w-muted">还没有提交记录</text></view></view></view></template>
<script setup>
import { computed,ref } from 'vue'
import { onLoad,onShow } from '@dcloudio/uni-app'
import { wishCredentials } from '@/common/wish-api.js'
import { chooseDoc,uploadTo,absUrl,openFile } from '@/common/upload.js'
import { toast } from '@/common/screen.js'
import { sheet } from '@/common/ui.js'
const types=[{key:'health',label:'健康证'},{key:'food',label:'食品经营许可证'},{key:'permit',label:'当地特殊许可'},{key:'payout',label:'收款资料'}]
const type=ref('health'),city=ref(''),file=ref(''),busy=ref(false),rows=ref([]),error=ref('')
const validFrom=ref(''),validUntil=ref(''),permitType=ref('')
const scopes=[{key:'tobacco',label:'烟草'},{key:'alcohol',label:'酒类'},{key:'both',label:'烟草及酒类'}]
const tip=computed(()=>({health:'食品类服务者提供有效健康证。',food:'食品类服务者提供有效食品经营许可证。',permit:'烟草、酒类默认不开放，特殊许可须单独核实当地条件。',payout:'有偿心愿完成后，用于平台核实并向服务者打款。'}[type.value]))
function stateLabel(r){if(r.status==='approved'&&r.type!=='payout'){const today=new Date(Date.now()+8*60*60*1000).toISOString().slice(0,10);if(!r.validFrom||!r.validUntil)return '需补充有效期';if(r.validUntil<today)return '证件已过期';if(r.validFrom>today)return '尚未生效'}return {pending:'审核中',approved:'已通过',rejected:'未通过'}[r.status]||r.status}
onLoad(q=>{if(types.some(t=>t.key===q.type))type.value=q.type});onShow(load)
async function load(){try{rows.value=(await wishCredentials()).data;error.value=''}catch(e){rows.value=[];error.value=e.message||'资料加载失败'}}
async function pick(){if(busy.value)return;try{const n=await sheet(['从相册选择','拍照','选择文件']);if(n<0)return;const p=await chooseDoc(['album','camera','file'][n]);if(p)file.value=p}catch(e){toast(e.message||'无法选择文件')}}
async function submit(){if(busy.value||!file.value)return;if(type.value==='permit'&&city.value.trim().length<2){toast('请填写许可适用城市');return}if(type.value!=='payout'&&(!validFrom.value||!validUntil.value||validUntil.value<validFrom.value)){toast('请填写证件上的完整有效期');return}if(type.value==='permit'&&!permitType.value){toast('请选择许可证实际涵盖范围');return}busy.value=true;try{await uploadTo('/app/wishes/credentials',file.value,{type:type.value,city:city.value.trim(),validFrom:validFrom.value,validUntil:validUntil.value,permitType:permitType.value});file.value='';toast('资料已提交审核');await load()}catch(e){toast(e.message||'上传失败，请重试')}finally{busy.value=false}}
async function view(r){try{if(/\.pdf(?:\?|&|$)/i.test(r.url))await openFile(r.url,true);else uni.previewImage({urls:[absUrl(r.url)]})}catch(e){toast(e.message||'文件预览失败，请刷新后重试')}}
</script>
<style lang="scss">@import './wish.scss';.wc-heading{padding:8px 0 27px;position:relative}.wc-heading__icon{position:absolute;right:12px;top:17px;padding:16px;background:#e7f58a;border-radius:23px;transform:rotate(8deg)}.wc-heading .w-caption{margin-top:20px}.wc-upload{background:#f3f6fc;border:1px dashed #b7c9e7;border-radius:17px;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:12px;padding:33px 10px;margin:22px 0;color:#102c46;font-size:13px;font-weight:650}.wc-upload text+text{font-size:10px;color:#8798af;font-weight:400}.wc-record{margin-top:14px;font-size:13px;font-weight:650}.wc-record .w-caption{font-weight:400}.wc-dates{display:grid;grid-template-columns:88px minmax(0,1fr);gap:14px 8px}.wc-dates .w-field__label{width:auto;white-space:nowrap}.wc-dates picker{min-width:0;width:100%}.wc-dates .w-input{font-size:12px;white-space:nowrap;display:flex;align-items:center;padding:0 12px;height:44px}</style>
